"use client"

import { type AgentControlBarControls } from "@/components/voice-agents/livekit/agent-control-bar"
import { AgentSessionProvider } from "@/components/voice-agents/livekit/agent-session-provider"
import type { AudioVisualizerConfig } from "@/components/voice-agents/livekit/blocks/agent-session-view-01/components/agent-session-block"
import { useAgent, useSession } from "@livekit/components-react"
import {
  type TokenSourceConfigurable,
  type TokenSourceFixed,
} from "livekit-client"
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type ComponentProps,
} from "react"
import { PopupView } from "./popup-view"
import { Trigger } from "./trigger"

const DEFAULT_CONTROLS: AgentControlBarControls = {
  leave: false,
  microphone: true,
  chat: false,
  camera: false,
  screenShare: false,
}

export interface AgentPopupError {
  title: string
  description: string
}

function TriggerProvider({ ...props }: ComponentProps<typeof Trigger>) {
  const { isConnected } = useAgent()

  return <Trigger {...props} isConnected={isConnected} />
}

export interface AgentPopupProps {
  /** Logo shown in the trigger bubble in place of the default agent icon. */
  logo?: string
  /** @default 'Agent' */
  agentName?: string
  /** Where to fetch a LiveKit session token from. See `useSession`'s `tokenSource` argument. */
  tokenSource: TokenSourceConfigurable | TokenSourceFixed
  /** Retained for API compatibility with LiveKit's complete popup block. */
  themeMode?: "dark" | "light"
  /**
   * Message shown above the controls before the first chat message is sent.
   *
   * @default 'Agent is listening, ask it a question'
   */
  preConnectMessage?: string
  /**
   * An object with the following keys: leave, microphone, screenShare, camera, chat. Each key maps
   * to a boolean value that determines whether the control is displayed.
   *
   * @default { leave: false, microphone: true, chat: false, camera: false, screenShare: false }
   */
  controls?: AgentControlBarControls
  /** Brand color used for the trigger bubble's idle ring/disc and fallback icon contrast. */
  triggerColor?: `#${string}`
  /**
   * Shows a pre-connect buffer state with a shimmer message before messages appear.
   *
   * @default true
   */
  isPreConnectBufferEnabled?: boolean
  /**
   * Configures the visualizer style rendered in the main tile area.
   *
   * @default { type: 'bar', size: 'lg' }
   */
  audioVisualizer?: AudioVisualizerConfig
}

export function AgentPopup_01({
  logo,
  themeMode,
  tokenSource,
  triggerColor,
  agentName = "Agent",
  controls = DEFAULT_CONTROLS,
  isPreConnectBufferEnabled,
  preConnectMessage,
  audioVisualizer = {
    type: "bar",
    size: "lg",
  },
}: AgentPopupProps) {
  const session = useSession(tokenSource)
  const [popupOpen, setPopupOpen] = useState(false)
  const [error, setError] = useState<AgentPopupError>()

  // Drive the session lifecycle off the popup-open state. Opening the popup
  // connects; closing it (or unmounting) tears the room down so we don't
  // leave a mic-hot connection while the bubble sits idle.
  //
  // useSession returns a fresh object on every connectionState change (the
  // discriminated union swaps shape), so we can't depend on `session`
  // directly - that would tear down + restart the room every time it
  // transitioned through connecting -> connected. We pin the start/end
  // calls via a ref instead, and only react to popupOpen.
  const sessionRef = useRef(session)
  sessionRef.current = session

  useEffect(() => {
    if (!popupOpen) return
    let cancelled = false
    sessionRef.current.start().catch((cause) => {
      if (cancelled) return

      console.error("agent-popup-01: session.start failed:", cause)
      setError({
        title: "Could not connect to the agent",
        description: cause instanceof Error ? cause.message : String(cause),
      })
    })
    return () => {
      cancelled = true
      void sessionRef.current.end()
    }
  }, [popupOpen])

  const handleToggle = useCallback(() => {
    setPopupOpen((open) => {
      const next = !open
      if (!next) setError(undefined)
      return next
    })
  }, [])

  const finalControls = {
    ...DEFAULT_CONTROLS,
    ...controls,
  }

  return (
    <AgentSessionProvider session={session}>
      <TriggerProvider
        logo={logo}
        error={error}
        color={triggerColor}
        agentName={agentName}
        isPressed={popupOpen}
        onToggle={handleToggle}
        className="fixed right-4 bottom-4 z-50"
      />
      {popupOpen && (
        <PopupView
          logo={logo}
          error={error}
          agentName={agentName}
          themeMode={themeMode}
          isPreConnectBufferEnabled={isPreConnectBufferEnabled}
          preConnectMessage={preConnectMessage}
          audioVisualizer={audioVisualizer}
          controls={finalControls}
          onDisconnect={handleToggle}
        />
      )}
    </AgentSessionProvider>
  )
}

"use client"

import { Button } from "@/components/voice-agents/livekit/_ui/button"
import { Toggle } from "@/components/voice-agents/livekit/_ui/toggle"
import { AgentDisconnectButton } from "@/components/voice-agents/livekit/agent-disconnect-button"
import { AgentTrackControl } from "@/components/voice-agents/livekit/agent-track-control"
import {
  AgentTrackToggle,
  agentTrackToggleVariants,
} from "@/components/voice-agents/livekit/agent-track-toggle"
import {
  useInputControls,
  usePublishPermissions,
  type UseInputControlsProps,
} from "@/components/voice-agents/livekit/hooks/use-agent-control-bar"
import { cn } from "@/lib/utils"
import { useChat } from "@livekit/components-react"
import { Track } from "livekit-client"
import { Loader, MessageSquareTextIcon, SendHorizontal } from "lucide-react"
import { motion, type MotionProps } from "motion/react"
import { useEffect, useRef, useState, type ComponentProps } from "react"

const LK_TOGGLE_VARIANT_1 = [
  "data-[state=off]:bg-accent data-[state=off]:hover:bg-foreground/10",
  "data-[state=off]:[&_~_button]:bg-accent data-[state=off]:[&_~_button]:hover:bg-foreground/10",
  "data-[state=off]:border-border data-[state=off]:hover:border-foreground/12",
  "data-[state=off]:[&_~_button]:border-border data-[state=off]:[&_~_button]:hover:border-foreground/12",
  "data-[state=off]:text-destructive data-[state=off]:hover:text-destructive data-[state=off]:focus:text-destructive",
  "data-[state=off]:focus-visible:ring-foreground/12 data-[state=off]:focus-visible:border-ring",
  "dark:data-[state=off]:[&_~_button]:bg-accent dark:data-[state=off]:[&_~_button]:hover:bg-foreground/10",
]

const LK_TOGGLE_VARIANT_2 = [
  "data-[state=off]:bg-accent data-[state=off]:hover:bg-foreground/10",
  "data-[state=off]:border-border data-[state=off]:hover:border-foreground/12",
  "data-[state=off]:focus-visible:border-ring data-[state=off]:focus-visible:ring-foreground/12",
  "data-[state=off]:text-foreground data-[state=off]:hover:text-foreground data-[state=off]:focus:text-foreground",
  "data-[state=on]:bg-blue-500/20 data-[state=on]:hover:bg-blue-500/30",
  "data-[state=on]:border-blue-700/10 data-[state=on]:text-blue-700 data-[state=on]:ring-blue-700/30",
  "data-[state=on]:focus-visible:border-blue-700/50",
  "dark:data-[state=on]:bg-blue-500/20 dark:data-[state=on]:text-blue-300",
]

const MOTION_PROPS: MotionProps = {
  variants: {
    hidden: {
      height: 0,
      opacity: 0,
      marginBottom: 0,
    },
    visible: {
      height: "auto",
      opacity: 1,
      marginBottom: 12,
    },
  },
  initial: "hidden",
  transition: {
    duration: 0.3,
    ease: "easeOut",
  },
}

interface AgentChatInputProps {
  chatOpen: boolean
  onSend?: (message: string) => void
  className?: string
}

function AgentChatInput({
  chatOpen,
  onSend = async () => {},
  className,
}: AgentChatInputProps) {
  const inputRef = useRef<HTMLTextAreaElement>(null)
  const [isSending, setIsSending] = useState(false)
  const [message, setMessage] = useState<string>("")
  const isDisabled = isSending || message.trim().length === 0

  const handleSend = async () => {
    if (isDisabled) {
      return
    }

    try {
      setIsSending(true)
      await onSend(message.trim())
      setMessage("")
    } catch (error) {
      console.error(error)
    } finally {
      setIsSending(false)
    }
  }

  const handleKeyDown = async (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }

  const handleButtonClick = async () => {
    if (isDisabled) return
    await handleSend()
  }

  useEffect(() => {
    if (chatOpen) return
    // when not disabled refocus on input
    inputRef.current?.focus()
  }, [chatOpen])

  return (
    <div
      className={cn(
        "mb-3 flex grow items-end gap-2 rounded-md pl-1 text-sm",
        className
      )}
    >
      <textarea
        autoFocus
        ref={inputRef}
        value={message}
        disabled={!chatOpen || isSending}
        placeholder="Type something..."
        onKeyDown={handleKeyDown}
        onChange={(e) => setMessage(e.target.value)}
        className="field-sizing-content max-h-16 min-h-8 flex-1 resize-none py-2 [scrollbar-width:thin] focus:outline-none disabled:cursor-not-allowed disabled:opacity-50"
      />
      <Button
        size="icon"
        type="button"
        disabled={isDisabled}
        variant={isDisabled ? "secondary" : "default"}
        title={isSending ? "Sending..." : "Send"}
        onClick={handleButtonClick}
        className="self-end disabled:cursor-not-allowed"
      >
        {isSending ? <Loader className="animate-spin" /> : <SendHorizontal />}
      </Button>
    </div>
  )
}

/** Configuration for which controls to display in the AgentControlBar. */
export interface AgentControlBarControls {
  /**
   * Whether to show the leave/disconnect button.
   *
   * @defaultValue true
   */
  leave?: boolean
  /**
   * Whether to show the camera toggle control.
   *
   * @defaultValue true (if camera publish permission is granted)
   */
  camera?: boolean
  /**
   * Whether to show the microphone toggle control.
   *
   * @defaultValue true (if microphone publish permission is granted)
   */
  microphone?: boolean
  /**
   * Whether to show the screen share toggle control.
   *
   * @defaultValue true (if screen share publish permission is granted)
   */
  screenShare?: boolean
  /**
   * Whether to show the chat toggle control.
   *
   * @defaultValue true (if data publish permission is granted)
   */
  chat?: boolean
}

export interface AgentControlBarProps extends UseInputControlsProps {
  /**
   * The visual style of the control bar.
   *
   * @default 'default'
   */
  variant?: "default" | "outline" | "livekit"
  /**
   * This takes an object with the following keys: `leave`, `microphone`, `screenShare`, `camera`,
   * `chat`. Each key maps to a boolean value that determines whether the control is displayed.
   *
   * @default
   * {
   *   leave: true,
   *   microphone: true,
   *   screenShare: true,
   *   camera: true,
   *   chat: true,
   * }
   */
  controls?: AgentControlBarControls
  /**
   * Whether to save user choices.
   *
   * @default true
   */
  saveUserChoices?: boolean
  /**
   * Whether the agent is connected to a session.
   *
   * @default false
   */
  isConnected?: boolean
  /**
   * Whether the chat input interface is open.
   *
   * @default false
   */
  isChatOpen?: boolean
  /** The callback for when the user disconnects. */
  onDisconnect?: () => void
  /** The callback for when the chat is opened or closed. */
  onIsChatOpenChange?: (open: boolean) => void
  /** The callback for when a device error occurs. */
  onDeviceError?: (error: { source: Track.Source; error: Error }) => void
}

/**
 * A control bar specifically designed for voice assistant interfaces. Provides controls for
 * microphone, camera, screen share, chat, and disconnect. Includes an expandable chat input for
 * text-based interaction with the agent.
 *
 * @example
 *
 * ```tsx
 * <AgentControlBar
 *   variant="livekit"
 *   isConnected={true}
 *   onDisconnect={() => handleDisconnect()}
 *   controls={{
 *     microphone: true,
 *     camera: true,
 *     screenShare: false,
 *     chat: true,
 *     leave: true,
 *   }}
 * />;
 * ```
 *
 * @extends ComponentProps<'div'>
 */
export function AgentControlBar({
  variant = "default",
  controls,
  isChatOpen = false,
  isConnected = false,
  saveUserChoices = true,
  onDisconnect,
  onDeviceError,
  onIsChatOpenChange,
  className,
  ...props
}: AgentControlBarProps & ComponentProps<"div">) {
  const { send } = useChat()
  const publishPermissions = usePublishPermissions()
  const [isChatOpenUncontrolled, setIsChatOpenUncontrolled] =
    useState(isChatOpen)
  const {
    microphoneTrack,
    cameraToggle,
    microphoneToggle,
    screenShareToggle,
    handleAudioDeviceChange,
    handleVideoDeviceChange,
    handleMicrophoneDeviceSelectError,
    handleCameraDeviceSelectError,
  } = useInputControls({ onDeviceError, saveUserChoices })

  const handleSendMessage = async (message: string) => {
    await send(message)
  }

  const visibleControls = {
    leave: controls?.leave ?? true,
    microphone: controls?.microphone ?? publishPermissions.microphone,
    screenShare: controls?.screenShare ?? publishPermissions.screenShare,
    camera: controls?.camera ?? publishPermissions.camera,
    chat: controls?.chat ?? publishPermissions.data,
  }

  const isEmpty = Object.values(visibleControls).every((value) => !value)

  if (isEmpty) {
    console.warn(
      "AgentControlBar: `visibleControls` contains only false values."
    )
    return null
  }

  return (
    <div
      aria-label="Voice assistant controls"
      className={cn(
        "bg-background border-input/50 dark:border-muted @container/agent-control-bar flex flex-col border p-3 drop-shadow-md/3",
        variant === "livekit" ? "rounded-[31px]" : "rounded-lg",
        className
      )}
      {...props}
    >
      <motion.div
        {...MOTION_PROPS}
        inert={!(isChatOpen || isChatOpenUncontrolled)}
        animate={isChatOpen || isChatOpenUncontrolled ? "visible" : "hidden"}
        className="border-input/50 flex w-full items-start overflow-hidden border-b"
      >
        <AgentChatInput
          chatOpen={isChatOpen || isChatOpenUncontrolled}
          onSend={handleSendMessage}
          className={cn(variant === "livekit" && "[&_button]:rounded-full")}
        />
      </motion.div>

      <div className="flex gap-1">
        <div className="flex grow gap-1">
          {/* Toggle Microphone */}
          {visibleControls.microphone && (
            <AgentTrackControl
              variant={variant === "outline" ? "outline" : "default"}
              kind="audioinput"
              aria-label="Toggle microphone"
              source={Track.Source.Microphone}
              pressed={microphoneToggle.enabled}
              disabled={microphoneToggle.pending}
              audioTrack={microphoneTrack}
              onPressedChange={microphoneToggle.toggle}
              onActiveDeviceChange={handleAudioDeviceChange}
              onMediaDeviceError={handleMicrophoneDeviceSelectError}
              className={cn(
                variant === "livekit" && [
                  LK_TOGGLE_VARIANT_1,
                  "rounded-full [&_button:first-child]:rounded-l-full [&_button:last-child]:rounded-r-full",
                ]
              )}
            />
          )}

          {/* Toggle Camera */}
          {visibleControls.camera && (
            <AgentTrackControl
              variant={variant === "outline" ? "outline" : "default"}
              kind="videoinput"
              aria-label="Toggle camera"
              source={Track.Source.Camera}
              pressed={cameraToggle.enabled}
              pending={cameraToggle.pending}
              disabled={cameraToggle.pending}
              onPressedChange={cameraToggle.toggle}
              onMediaDeviceError={handleCameraDeviceSelectError}
              onActiveDeviceChange={handleVideoDeviceChange}
              className={cn(
                variant === "livekit" && [
                  LK_TOGGLE_VARIANT_1,
                  "rounded-full [&_button:first-child]:rounded-l-full [&_button:last-child]:rounded-r-full",
                ]
              )}
            />
          )}

          {/* Toggle Screen Share */}
          {visibleControls.screenShare && (
            <AgentTrackToggle
              variant={variant === "outline" ? "outline" : "default"}
              aria-label="Toggle screen share"
              source={Track.Source.ScreenShare}
              pressed={screenShareToggle.enabled}
              disabled={screenShareToggle.pending}
              onPressedChange={screenShareToggle.toggle}
              className={cn(
                variant === "livekit" && [LK_TOGGLE_VARIANT_2, "rounded-full"]
              )}
            />
          )}

          {/* Toggle Transcript */}
          {visibleControls.chat && (
            <Toggle
              variant={variant === "outline" ? "outline" : "default"}
              pressed={isChatOpen || isChatOpenUncontrolled}
              aria-label="Toggle transcript"
              onPressedChange={(state) => {
                if (!onIsChatOpenChange) setIsChatOpenUncontrolled(state)
                else onIsChatOpenChange(state)
              }}
              className={agentTrackToggleVariants({
                variant: variant === "outline" ? "outline" : "default",
                className: cn(
                  variant === "livekit" && [LK_TOGGLE_VARIANT_2, "rounded-full"]
                ),
              })}
            >
              <MessageSquareTextIcon />
            </Toggle>
          )}
        </div>

        {/* Disconnect */}
        {visibleControls.leave && (
          <AgentDisconnectButton
            onClick={onDisconnect}
            disabled={!isConnected}
            className={cn(
              variant === "livekit" &&
                "bg-destructive/10 dark:bg-destructive/10 text-destructive hover:bg-destructive/20 dark:hover:bg-destructive/20 focus:bg-destructive/20 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/4 rounded-full font-mono text-xs font-bold tracking-wider"
            )}
          >
            <span className="sr-only uppercase @sm/agent-control-bar:not-sr-only">
              End{" "}
              <span className="sr-only @md/agent-control-bar:not-sr-only">
                call
              </span>
            </span>
          </AgentDisconnectButton>
        )}
      </div>
    </div>
  )
}

import { cn } from "@/lib/utils"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "radix-ui"
import * as React from "react"

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function getSitePathname(
  pathname: string,
  basePath = process.env.NEXT_PUBLIC_BASE_PATH || ""
) {
  const base = basePath.replace(/\/+$/, "")
  const path =
    pathname === base || pathname.startsWith(`${base}/`)
      ? pathname.slice(base.length)
      : pathname
  return path.replace(/\/+$/, "") || "/"
}

/**
 * Get the base URL depending on the current environment
 */
export function getBaseUrl() {
  const basePath = (process.env.NEXT_PUBLIC_BASE_PATH || "").replace(/\/$/, "")
  const withBasePath = (url: string) => {
    const base = url.replace(/\/$/, "")
    return basePath && !base.endsWith(basePath) ? `${base}${basePath}` : base
  }
  // For server-side rendering, we need to use environment variables
  if (typeof window === "undefined") {
    // Check for Vercel-specific environment variables
    // Production URL takes precedence if available (works in all environments)
    if (process.env.NEXT_PUBLIC_VERCEL_PROJECT_PRODUCTION_URL) {
      return withBasePath(
        `https://${process.env.NEXT_PUBLIC_VERCEL_PROJECT_PRODUCTION_URL}`
      )
    }

    // For branch deployments
    if (process.env.NEXT_PUBLIC_VERCEL_BRANCH_URL) {
      return withBasePath(
        `https://${process.env.NEXT_PUBLIC_VERCEL_BRANCH_URL}`
      )
    }

    // For regular deployments
    if (process.env.NEXT_PUBLIC_VERCEL_URL) {
      return withBasePath(`https://${process.env.NEXT_PUBLIC_VERCEL_URL}`)
    }

    // Legacy support
    if (process.env.VERCEL_URL) {
      return withBasePath(`https://${process.env.VERCEL_URL}`)
    }

    // Fall back to explicitly set environment variables
    if (process.env.NEXT_PUBLIC_BASE_URL) {
      return withBasePath(process.env.NEXT_PUBLIC_BASE_URL)
    }

    // Default for development - check PORT env var first
    const port = process.env.PORT || 3000
    return withBasePath(
      process.env.NODE_ENV === "development" ? `http://localhost:${port}` : ""
    )
  }

  // For client-side, we can just use the browser's location
  return withBasePath(window.location.origin)
}

"use client"

import { cn } from "@/lib/utils"
import { cva, type VariantProps } from "class-variance-authority"
import { Toggle as TogglePrimitive } from "radix-ui"
import * as React from "react"

const toggleVariants = cva(
  "inline-flex items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-[color,box-shadow] outline-none hover:bg-muted hover:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        outline:
          "border border-input bg-transparent shadow-xs hover:bg-accent hover:text-accent-foreground",
      },
      size: {
        default: "h-9 min-w-9 px-2",
        sm: "h-8 min-w-8 px-1.5",
        lg: "h-10 min-w-10 px-2.5",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Toggle({
  className,
  variant,
  size,
  ...props
}: React.ComponentProps<typeof TogglePrimitive.Root> &
  VariantProps<typeof toggleVariants>) {
  return (
    <TogglePrimitive.Root
      data-slot="toggle"
      className={cn(toggleVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Toggle, toggleVariants }

"use client"

import {
  Button,
  type buttonVariants,
