/**
 * Props for the AgentAudioVisualizerBar component.
 */
export interface AgentAudioVisualizerBarProps {
  /**
   * The size of the visualizer.
   * @defaultValue 'md'
   */
  size?: "icon" | "sm" | "md" | "lg" | "xl"
  /**
   * The current state of the agent. Determines the animation pattern.
   * @defaultValue 'connecting'
   */
  state?: AgentState
  /**
   * The color of the bars in hexidecimal format.
   */
  color?: `#${string}`
  /**
   * The number of bars to display in the visualizer.
   * If not provided, defaults based on size: 3 for 'icon'/'sm', 5 for others.
   */
  barCount?: number
  /**
   * The audio track to visualize. Can be a local/remote audio track or a track reference.
   */
  audioTrack?: LocalAudioTrack | RemoteAudioTrack | TrackReferenceOrPlaceholder
  /**
   * Volume values (0-1) to use instead of the values computed from the audioTrack.
   * The volumeBands.length should match barCount.
   */
  volumeBands?: number[]
  /**
   * Additional CSS class names to apply to the container.
   */
  className?: string
  /**
   * Custom div element to render as grid cells. Each child receives data-lk-index,
   * data-lk-highlighted props and style props for height. Must be a single div element.
   */
  children?: ReactNode
}

/**
 * A bar-style audio visualizer that responds to agent state and audio levels.
 * Displays animated bars that react to the current agent state (connecting, thinking, speaking, etc.)
 * and audio volume when speaking.
 *
 * @extends ComponentProps<'div'>
 *
 * @example
 * ```tsx
 * <AgentAudioVisualizerBar
 *   size="md"
 *   state="speaking"
 *   audioTrack={agentAudioTrack}
 * />
 * ```
 */
export function AgentAudioVisualizerBar({
  size = "md",
  state = "connecting",
  color,
  barCount,
  audioTrack,
  volumeBands,
  className,
  children,
  style,
  ...props
}: AgentAudioVisualizerBarProps &
  VariantProps<typeof AgentAudioVisualizerBarVariants> &
  ComponentProps<"div">) {
  const _barCount = useMemo(() => {
    if (barCount) {
      return barCount
    }
    switch (size) {
      case "icon":
      case "sm":
        return 3
      default:
        return 5
    }
  }, [barCount, size])

  const multibandVolume = useMultibandTrackVolume(audioTrack, {
    bands: _barCount,
    loPass: 100,
    hiPass: 200,
  })
  const resolvedVolumeBands = volumeBands
    ? normalizeVolumeBands(volumeBands, _barCount)
    : multibandVolume

  const sequencerInterval = useMemo(() => {
    switch (state) {
      case "connecting":
        return 2000 / _barCount
      case "initializing":
        return 2000
      case "listening":
        return 500
      case "thinking":
        return 150
      default:
        return 1000
    }
  }, [state, _barCount])

  const highlightedIndices = useAgentAudioVisualizerBarAnimator(
    state,
    _barCount,
    sequencerInterval
  )

  const bands = useMemo(
    () =>
      state === "speaking" ? resolvedVolumeBands : new Array(_barCount).fill(0),
    [state, resolvedVolumeBands, _barCount]
  )

  if (children && Array.isArray(children)) {
    throw new Error(
      "AgentAudioVisualizerBar children must be a single element."
    )
  }

  return (
    <div
      data-lk-state={state}
      style={{ ...style, color } as CSSProperties}
      className={cn(AgentAudioVisualizerBarVariants({ size }), className)}
      {...props}
    >
      {bands.map((band: number, idx: number) =>
        children ? (
          <React.Fragment key={idx}>
            {cloneSingleChild(children, {
              "data-lk-index": idx,
              "data-lk-highlighted": highlightedIndices.includes(idx),
              style: { height: `${band * 100}%` },
            })}
          </React.Fragment>
        ) : (
          <div
            key={idx}
            data-lk-index={idx}
            data-lk-highlighted={highlightedIndices.includes(idx)}
            style={{ height: `${band * 100}%` }}
            className={cn(AgentAudioVisualizerBarElementVariants({ size }))}
          />
        )
      )}
    </div>
  )
}

import { type AgentState } from "@livekit/components-react"
import { useReducedMotion } from "motion/react"
import { useEffect, useRef, useState } from "react"

function generateConnectingSequenceBar(columns: number): number[][] {
  const seq = []

  for (let x = 0; x < columns; x++) {
    seq.push([x, columns - 1 - x])
  }

  return seq
}

function generateListeningSequenceBar(columns: number): number[][] {
  const center = Math.floor(columns / 2)
  const noIndex = -1

  return [[center], [noIndex]]
}

export function useAgentAudioVisualizerBarAnimator(
  state: AgentState | undefined,
  columns: number,
  interval: number
): number[] {
  const prefersReducedMotion = useReducedMotion()
  const [index, setIndex] = useState(0)
  const [sequence, setSequence] = useState<number[][]>([[]])

  useEffect(() => {
    if (state === "thinking") {
      setSequence(generateListeningSequenceBar(columns))
    } else if (state === "connecting" || state === "initializing") {
      const sequence = [...generateConnectingSequenceBar(columns)]
      setSequence(sequence)
    } else if (state === "listening") {
      setSequence(generateListeningSequenceBar(columns))
    } else if (state === undefined || state === "speaking") {
      setSequence([new Array(columns).fill(0).map((_, idx) => idx)])
    } else {
      setSequence([[]])
    }
    setIndex(0)
  }, [state, columns])

  const animationFrameId = useRef<number | null>(null)
  useEffect(() => {
    if (prefersReducedMotion || sequence.length <= 1) return

    let startTime = performance.now()

    const animate = (time: DOMHighResTimeStamp) => {
      const timeElapsed = time - startTime

      if (timeElapsed >= interval) {
        setIndex((prev) => prev + 1)
        startTime = time
      }

      animationFrameId.current = requestAnimationFrame(animate)
    }

    animationFrameId.current = requestAnimationFrame(animate)

    return () => {
      if (animationFrameId.current !== null) {
        cancelAnimationFrame(animationFrameId.current)
      }
    }
  }, [interval, columns, state, sequence.length, prefersReducedMotion])

  return sequence[prefersReducedMotion ? 0 : index % sequence.length] ?? []
}

