/**
 * A radial (circular) audio visualizer that responds to agent state and audio levels.
 * Displays animated bars arranged in a circle that react to the current agent state
 * and audio volume when speaking.
 *
 * @extends ComponentProps<'div'>
 *
 * @example
 * ```tsx
 * <AgentAudioVisualizerRadial
 *   size="lg"
 *   state="speaking"
 *   barCount={24}
 *   audioTrack={agentAudioTrack}
 * />
 * ```
 */
export function AgentAudioVisualizerRadial({
  size = "md",
  state = "connecting",
  color,
  radius,
  barCount,
  audioTrack,
  volumeBands,
  className,
  style,
  ...props
}: AgentAudioVisualizerRadialProps &
  ComponentProps<"div"> &
  VariantProps<typeof AgentAudioVisualizerRadialVariants>) {
  const _barCount = useMemo(() => {
    if (barCount) {
      return barCount
    }
    switch (size) {
      case "icon":
      case "sm":
        return 12
      default:
        return 24
    }
  }, [barCount, size])

  const multibandVolume = useMultibandTrackVolume(audioTrack, {
    bands: _barCount,
    loPass: 100,
    hiPass: 200,
  })
  const resolvedVolumeBands = volumeBands
    ? normalizeVolumeBands(volumeBands, _barCount)
    : multibandVolume

  const sequencerInterval = useMemo(() => {
    switch (state) {
      case "connecting":
      case "listening":
        return 500
      case "initializing":
        return 250
      case "thinking":
        return Infinity
      default:
        return 1000
    }
  }, [state])

  const distanceFromCenter = useMemo(() => {
    if (radius) {
      return radius
    }
    switch (size) {
      case "icon":
        return 6
      case "xl":
        return 128
      case "lg":
        return 64
      case "sm":
        return 16
      case "md":
      default:
        return 32
    }
  }, [size, radius])

  if (_barCount % 4 !== 0) {
    console.warn("barCount should be divisible by 4 for optimal visual results")
  }

  const highlightedIndices = useAgentAudioVisualizerRadialAnimator(
    state,
    _barCount,
    sequencerInterval
  )

  const dotSize = useMemo(() => {
    return (distanceFromCenter * Math.PI) / _barCount
  }, [distanceFromCenter, _barCount])

  return (
    <div
      data-lk-state={state}
      className={cn(
        AgentAudioVisualizerRadialVariants({ size }),
        "relative",
        className
      )}
      style={{ ...style, color } as CSSProperties}
      {...props}
    >
      {resolvedVolumeBands.map((band, idx) => {
        const angle = (idx / _barCount) * Math.PI * 2

        return (
          <div
            key={`${_barCount}-${idx}`}
            data-lk-state={state}
            className="absolute top-1/2 left-1/2 h-1 w-1 -translate-x-1/2 -translate-y-1/2"
            style={{
              transformOrigin: "center",
              transform: `rotate(${angle}rad) translateY(${distanceFromCenter}px)`,
            }}
          >
            <div
              data-lk-index={idx}
              data-lk-highlighted={highlightedIndices.includes(idx)}
              style={{
                width: dotSize,
                minHeight: dotSize,
                height: state === "speaking" ? `${dotSize * 10 * band}px` : 0,
              }}
            />
          </div>
        )
      })}
    </div>
  )
}

import { type AgentState } from "@livekit/components-react"
import { useReducedMotion } from "motion/react"
import { useEffect, useRef, useState } from "react"

function findGcdLessThan(columns: number, max: number = columns): number {
  function gcd(a: number, b: number): number {
    while (b !== 0) {
      const t = b
      b = a % b
      a = t
    }
    return a
  }
  for (let i = max; i >= 1; i--) {
    if (gcd(columns, i) === i) {
      return i
    }
  }
  return 1
}

function generateConnectingSequenceBar(columns: number): number[][] {
  const seq = []
  const center = Math.floor(columns / 2)

  for (let x = 0; x < columns; x++) {
    seq.push([x, (x + center) % columns])
  }

  return seq
}

function generateListeningSequenceBar(columns: number): number[][] {
  const divisor =
    columns > 8
      ? columns / findGcdLessThan(columns, 4)
      : findGcdLessThan(columns, 2)

  return Array.from({ length: divisor }, (_, idx) => [
    ...Array(Math.floor(columns / divisor))
      .fill(1)
      .map((_, idx2) => idx2 * divisor + idx),
  ])
}

export const useAgentAudioVisualizerRadialAnimator = (
  state: AgentState | undefined,
  barCount: number,
  interval: number
): number[] => {
  const prefersReducedMotion = useReducedMotion()
  const [index, setIndex] = useState(0)
  const [sequence, setSequence] = useState<number[][]>([[]])

  useEffect(() => {
    if (state === "thinking") {
      setSequence(generateListeningSequenceBar(barCount))
    } else if (state === "connecting" || state === "initializing") {
      setSequence(generateConnectingSequenceBar(barCount))
    } else if (state === "listening") {
      setSequence(generateListeningSequenceBar(barCount))
    } else if (state === undefined || state === "speaking") {
      setSequence([new Array(barCount).fill(0).map((_, idx) => idx)])
    } else {
      setSequence([[]])
    }
    setIndex(0)
  }, [state, barCount])

  const animationFrameId = useRef<number | null>(null)
  useEffect(() => {
    if (
      prefersReducedMotion ||
      sequence.length <= 1 ||
      !Number.isFinite(interval)
    )
      return

    let startTime = performance.now()

    const animate = (time: DOMHighResTimeStamp) => {
      const timeElapsed = time - startTime

      if (timeElapsed >= interval) {
        setIndex((prev) => prev + 1)
        startTime = time
      }

      animationFrameId.current = requestAnimationFrame(animate)
    }

    animationFrameId.current = requestAnimationFrame(animate)

    return () => {
      if (animationFrameId.current !== null) {
        cancelAnimationFrame(animationFrameId.current)
      }
    }
  }, [interval, barCount, state, sequence.length, prefersReducedMotion])

  return sequence[prefersReducedMotion ? 0 : index % sequence.length] ?? []
}

