/**
 * A wave-style audio visualizer that responds to agent state and audio levels.
 * Displays an animated wave that reacts to the current agent state (connecting, thinking, speaking, etc.)
 * and audio volume when speaking.
 *
 * @extends ComponentProps<'div'>
 *
 * @example ```tsx
 * <AgentAudioVisualizerWave
 *   size="lg"
 *   state="speaking"
 *   color="#1FD5F9"
 *   colorShift={0.3}
 *   lineWidth={2}
 *   blur={0.5}
 *   audioTrack={audioTrack}
 * />
 * ```
 */
export function AgentAudioVisualizerWave({
  size = "lg",
  state = "speaking",
  color,
  colorShift = 0.05,
  lineWidth,
  blur,
  audioTrack,
  volume,
  className,
  ref,
  ...props
}: AgentAudioVisualizerWaveProps &
  ComponentProps<"div"> &
  VariantProps<typeof AgentAudioVisualizerWaveVariants>) {
  const _lineWidth = useMemo(() => {
    if (lineWidth !== undefined) {
      return lineWidth
    }
    switch (size) {
      case "icon":
      case "sm":
        return 2
      default:
        return 1
    }
  }, [lineWidth, size])

  const { speed, amplitude, frequency, opacity } = useAgentAudioVisualizerWave({
    state,
    audioTrack,
    volume,
  })

  return (
    <WaveShader
      ref={ref}
      data-lk-state={state}
      speed={speed}
      color={color}
      colorShift={colorShift}
      mix={opacity}
      amplitude={amplitude}
      frequency={frequency}
      lineWidth={_lineWidth}
      blur={blur}
      className={cn(
        AgentAudioVisualizerWaveVariants({ size }),
        "mask-[linear-gradient(90deg,transparent_0%,black_20%,black_80%,transparent_100%)]",
        className
      )}
      {...props}
    />
  )
}

import {
  useTrackVolume,
  type AgentState,
  type TrackReference,
  type TrackReferenceOrPlaceholder,
} from "@livekit/components-react"
import { LocalAudioTrack, RemoteAudioTrack } from "livekit-client"
import {
  animate,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
  type AnimationPlaybackControlsWithThen,
  type ValueAnimationTransition,
} from "motion/react"
import { useCallback, useEffect, useRef, useState } from "react"

const DEFAULT_SPEED = 5
const DEFAULT_AMPLITUDE = 0.025
const DEFAULT_FREQUENCY = 10
const DEFAULT_TRANSITION: ValueAnimationTransition = {
  duration: 0.2,
  ease: "easeOut",
}

function useAnimatedValue<T>(initialValue: T) {
  const [value, setValue] = useState(initialValue)
  const motionValue = useMotionValue(initialValue)
  const controlsRef = useRef<AnimationPlaybackControlsWithThen | null>(null)
  useMotionValueEvent(motionValue, "change", (value) => setValue(value as T))

  const animateFn = useCallback(
    (targetValue: T | T[], transition: ValueAnimationTransition) => {
      controlsRef.current = animate(motionValue, targetValue, transition)
    },
    [motionValue]
  )

  return { value, controls: controlsRef, animate: animateFn }
}

interface UseAgentAudioVisualizerWaveAnimatorArgs {
  state?: AgentState
  audioTrack?: LocalAudioTrack | RemoteAudioTrack | TrackReferenceOrPlaceholder
  volume?: number
}

export function useAgentAudioVisualizerWave({
  state,
  audioTrack,
  volume: volumeProp,
}: UseAgentAudioVisualizerWaveAnimatorArgs) {
  const prefersReducedMotion = useReducedMotion()
  const [speed, setSpeed] = useState(DEFAULT_SPEED)
  const { value: amplitude, animate: animateAmplitude } =
    useAnimatedValue(DEFAULT_AMPLITUDE)
  const { value: frequency, animate: animateFrequency } =
    useAnimatedValue(DEFAULT_FREQUENCY)
  const { value: opacity, animate: animateOpacity } = useAnimatedValue(1.0)

  const trackVolume = useTrackVolume(audioTrack as TrackReference, {
    fftSize: 512,
    smoothingTimeConstant: 0.55,
  })
  const volume = volumeProp ?? trackVolume

  useEffect(() => {
    switch (state) {
      case "disconnected":
        setSpeed(DEFAULT_SPEED)
        animateAmplitude(0, DEFAULT_TRANSITION)
        animateFrequency(0, DEFAULT_TRANSITION)
        animateOpacity(1.0, DEFAULT_TRANSITION)
        return
      case "listening":
        setSpeed(DEFAULT_SPEED)
        animateAmplitude(DEFAULT_AMPLITUDE, DEFAULT_TRANSITION)
        animateFrequency(DEFAULT_FREQUENCY, DEFAULT_TRANSITION)
        animateOpacity(
          prefersReducedMotion ? 0.65 : [1.0, 0.3],
          prefersReducedMotion
            ? { duration: 0 }
            : { duration: 0.75, repeat: Infinity, repeatType: "mirror" }
        )
        return
      case "thinking":
      case "connecting":
      case "initializing":
        setSpeed(DEFAULT_SPEED * 4)
        animateAmplitude(DEFAULT_AMPLITUDE / 4, DEFAULT_TRANSITION)
        animateFrequency(DEFAULT_FREQUENCY * 4, DEFAULT_TRANSITION)
        animateOpacity(
          prefersReducedMotion ? 0.65 : [1.0, 0.3],
          prefersReducedMotion
            ? { duration: 0 }
            : { duration: 0.4, repeat: Infinity, repeatType: "mirror" }
        )
        return
      case "speaking":
      default:
        setSpeed(DEFAULT_SPEED * 2)
        animateAmplitude(DEFAULT_AMPLITUDE, DEFAULT_TRANSITION)
        animateFrequency(DEFAULT_FREQUENCY, DEFAULT_TRANSITION)
        animateOpacity(1.0, DEFAULT_TRANSITION)
        return
    }
  }, [
    state,
    setSpeed,
    animateAmplitude,
    animateFrequency,
    animateOpacity,
    prefersReducedMotion,
  ])

  useEffect(() => {
    if (state === "speaking") {
      animateAmplitude(0.015 + 0.4 * volume, { duration: 0 })
      animateFrequency(20 + 60 * volume, { duration: 0 })
    }
  }, [state, volume, animateAmplitude, animateFrequency])

  return {
    speed,
    amplitude,
    frequency,
    opacity,
  }
}

