 * ```
 */
export function AgentChatIndicator({
  size = "md",
  className,
  ...props
}: AgentChatIndicatorProps &
  ComponentProps<"span"> &
  VariantProps<typeof agentChatIndicatorVariants>) {
  const prefersReducedMotion = useReducedMotion()

  return (
    <motion.span
      {...(prefersReducedMotion
        ? { initial: false, animate: { opacity: 1, scale: 1 } }
        : motionAnimationProps)}
      transition={{ duration: 0.1, ease: "linear" as const }}
      className={cn(agentChatIndicatorVariants({ size }), className)}
      {...props}
    />
  )
}

import { cn } from "@/lib/utils"
import {
  useLocalParticipant,
  useTracks,
  useVoiceAssistant,
  VideoTrack,
  type TrackReference,
} from "@livekit/components-react"
import { Track } from "livekit-client"
import { AnimatePresence, motion, type MotionProps } from "motion/react"
import React, { useMemo } from "react"
import { type AudioVisualizerConfig } from "./agent-session-block"
import { AudioVisualizer } from "./audio-visualizer"

const ANIMATION_TRANSITION: MotionProps["transition"] = {
  type: "spring",
  stiffness: 675,
  damping: 75,
  mass: 1,
}

const tileViewClassNames = {
  // GRID
  // 2 Columns x 3 Rows
  grid: [
    "h-full w-full",
    "grid gap-x-2 place-content-center",
    "grid-cols-[1fr_1fr] grid-rows-[90px_1fr_90px]",
  ],
  // Agent
  // chatOpen: true,
  // hasSecondTile: true
  // layout: Column 1 / Row 1
  // align: x-end y-center
  agentChatOpenWithSecondTile: [
    "col-start-1 row-start-1",
    "self-center justify-self-end",
  ],
  // Agent
  // chatOpen: true,
  // hasSecondTile: false
  // layout: Column 1 / Row 1 / Column-Span 2
  // align: x-center y-center
  agentChatOpenWithoutSecondTile: [
    "col-start-1 row-start-1",
    "col-span-2",
    "place-content-center",
  ],
  // Agent
  // chatOpen: false
  // layout: Column 1 / Row 1 / Column-Span 2 / Row-Span 3
  // align: x-center y-center
  agentChatClosed: [
    "col-start-1 row-start-1",
    "col-span-2 row-span-3",
    "place-content-center",
  ],
  // Second tile
  // chatOpen: true,
  // hasSecondTile: true
  // layout: Column 2 / Row 1
  // align: x-start y-center
  secondTileChatOpen: [
    "col-start-2 row-start-1",
    "self-center justify-self-start",
  ],
  // Second tile
  // chatOpen: false,
  // hasSecondTile: false
  // layout: Column 2 / Row 2
  // align: x-end y-end
  secondTileChatClosed: ["col-start-2 row-start-3", "place-content-end"],
}

export function useLocalTrackRef(source: Track.Source) {
  const { localParticipant } = useLocalParticipant()
  const publication = localParticipant.getTrackPublication(source)
  const trackRef = useMemo<TrackReference | undefined>(
    () =>
      publication
        ? { source, participant: localParticipant, publication }
        : undefined,
    [source, publication, localParticipant]
  )
  return trackRef
}

interface TileLayoutProps {
  isChatOpen: boolean
  audioVisualizer?: AudioVisualizerConfig
}

export function TileLayout({ isChatOpen, audioVisualizer }: TileLayoutProps) {
  const { videoTrack: agentVideoTrack } = useVoiceAssistant()
  const [screenShareTrack] = useTracks([Track.Source.ScreenShare])
  const cameraTrack: TrackReference | undefined = useLocalTrackRef(
    Track.Source.Camera
  )

  const isCameraEnabled = cameraTrack && !cameraTrack.publication.isMuted
  const isScreenShareEnabled =
    screenShareTrack && !screenShareTrack.publication.isMuted
  const hasSecondTile = isCameraEnabled || isScreenShareEnabled

  const animationDelay = isChatOpen ? 0 : 0.15
  const isAvatar = agentVideoTrack !== undefined
  const videoWidth = agentVideoTrack?.publication.dimensions?.width ?? 0
  const videoHeight = agentVideoTrack?.publication.dimensions?.height ?? 0

  const { type: audioVisualizerType = "bar", ...audioVisualizerConfig } =
    audioVisualizer ?? {}

  return (
    <div className="pointer-events-none absolute inset-x-0 top-8 bottom-24 z-50 @md/agent-session-block:top-12 @md/agent-session-block:bottom-40">
      <div className="relative mx-auto h-full max-w-2xl px-4 @md/agent-session-block:px-0">
        <div className={cn(tileViewClassNames.grid)}>
          {/* Agent */}
          <div
            className={cn([
              "grid",
              !isChatOpen && tileViewClassNames.agentChatClosed,
              isChatOpen &&
                hasSecondTile &&
                tileViewClassNames.agentChatOpenWithSecondTile,
              isChatOpen &&
                !hasSecondTile &&
                tileViewClassNames.agentChatOpenWithoutSecondTile,
            ])}
          >
            <AnimatePresence mode="popLayout">
              {!isAvatar && (
                // Audio Agent
                <motion.div
                  key="agent"
                  layoutId="agent"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{
                    ...ANIMATION_TRANSITION,
                    delay: animationDelay,
                  }}
                  className={cn("relative aspect-square h-[90px]")}
                >
                  <AudioVisualizer
                    key="audio-visualizer"
                    initial={{ scale: 1 }}
                    animate={{ scale: isChatOpen ? 0.2 : 1 }}
                    transition={{
                      ...ANIMATION_TRANSITION,
                      delay: animationDelay,
                    }}
                    type={audioVisualizerType}
                    config={audioVisualizerConfig}
                    className={cn(
                      "absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2",
                      "bg-background rounded-[50px] border border-transparent transition-[border,drop-shadow]",
                      isChatOpen && "border-input shadow-2xl/10 delay-200"
                    )}
                    style={{ color: audioVisualizer?.color }}
                  />
                </motion.div>
              )}

              {isAvatar && (
                // Avatar Agent
                <motion.div
                  key="avatar"
                  layoutId="avatar"
                  initial={{
                    scale: 1,
                    opacity: 1,
                    maskImage:
                      "radial-gradient(circle, rgba(0, 0, 0, 1) 0, rgba(0, 0, 0, 1) 20px, transparent 20px)",
                    filter: "blur(20px)",
                  }}
                  animate={{
                    maskImage:
                      "radial-gradient(circle, rgba(0, 0, 0, 1) 0, rgba(0, 0, 0, 1) 500px, transparent 500px)",
                    filter: "blur(0px)",
                    borderRadius: isChatOpen ? 6 : 12,
                  }}
                  transition={{
                    ...ANIMATION_TRANSITION,
                    delay: animationDelay,
                    maskImage: {
                      duration: 1,
                    },
                    filter: {
                      duration: 1,
                    },
                  }}
                  className={cn(
                    "overflow-hidden bg-black drop-shadow-xl/80",
                    isChatOpen ? "h-[90px]" : "h-auto w-full"
                  )}
                >
                  <VideoTrack
                    width={videoWidth}
                    height={videoHeight}
                    trackRef={agentVideoTrack}
                    className={cn(isChatOpen && "size-[90px] object-cover")}
                  />
                </motion.div>
              )}
            </AnimatePresence>
          </div>

          <div
            className={cn([
              "grid",
              isChatOpen && tileViewClassNames.secondTileChatOpen,
              !isChatOpen && tileViewClassNames.secondTileChatClosed,
            ])}
          >
            {/* Camera & Screen Share */}
            <AnimatePresence>
              {((cameraTrack && isCameraEnabled) ||
                (screenShareTrack && isScreenShareEnabled)) && (
                <motion.div
                  key="camera"
                  layout="position"
                  layoutId="camera"
                  initial={{
                    opacity: 0,
                    scale: 0,
                  }}
                  animate={{
                    opacity: 1,
                    scale: 1,
                  }}
                  exit={{
                    opacity: 0,
                    scale: 0,
                  }}
                  transition={{
                    ...ANIMATION_TRANSITION,
                    delay: animationDelay,
                  }}
                  className="aspect-square size-[90px] drop-shadow-lg/20"
                >
                  <VideoTrack
                    trackRef={cameraTrack || screenShareTrack}
                    width={
                      (cameraTrack || screenShareTrack)?.publication.dimensions
                        ?.width ?? 0
                    }
                    height={
                      (cameraTrack || screenShareTrack)?.publication.dimensions
                        ?.height ?? 0
                    }
                    className="bg-muted aspect-square size-[90px] rounded-md object-cover"
                  />
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>
      </div>
    </div>
  )
}

