interface ErrorOverlayProps {
  logo?: string
  agentName?: string
  error?: AgentPopupError
}

function ErrorOverlay({ logo, agentName, error }: ErrorOverlayProps) {
  const [logoFailed, setLogoFailed] = useState(false)
  useEffect(() => {
    setLogoFailed(false)
  }, [logo])
  const showLogo = Boolean(logo) && !logoFailed

  return error ? (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      data-testid="error-overlay"
      // @ts-expect-error React's types lag the platform on `inert`.
      inert={error === null ? "" : undefined}
      className={cn(
        "bg-background absolute inset-0 z-50 flex h-full w-full flex-col items-center justify-center gap-5 px-6 text-center transition-opacity"
      )}
    >
      {showLogo ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={logo}
          alt={`${agentName ?? "Agent"} logo`}
          className="size-6 object-contain"
          referrerPolicy="no-referrer"
          onError={() => setLogoFailed(true)}
        />
      ) : null}
      <span className="text-foreground leading-tight font-medium text-pretty">
        {error?.title}
      </span>
      <span className="text-muted-foreground text-sm text-balance">
        {error?.description}
      </span>
    </motion.div>
  ) : null
}

